from pathlib import Path

p=Path('sethiportfolio-admin.html')
s=p.read_text(encoding='utf-8')

old='''<div><label class="label" for="allocation-funding-symbol">Ticker</label><input id="allocation-funding-symbol" class="field uppercase" value="VUAG.L" required></div>'''
new='''<div><label class="label" for="allocation-funding-symbol">Ticker</label><input id="allocation-funding-symbol" class="field uppercase" value="VUAG.L" required><p id="allocation-funding-status" class="text-[10px] font-bold text-gray-400 mt-1.5">Enter a ticker to verify.</p></div>'''
if old not in s: raise SystemExit('funding ticker block missing')
s=s.replace(old,new,1)

old='''<div><label class="label" for="allocation-target-symbol">Ticker</label><input id="allocation-target-symbol" class="field uppercase" placeholder="e.g. LSEG.L" required></div><div><label class="label" for="allocation-target-name">Instrument name</label><input id="allocation-target-name" class="field" placeholder="Company name" required></div>'''
new='''<div><label class="label" for="allocation-target-symbol">Ticker</label><input id="allocation-target-symbol" class="field uppercase" placeholder="e.g. LSEG.L" required><p id="allocation-target-status" class="text-[10px] font-bold text-gray-400 mt-1.5">Enter a ticker to verify.</p></div><div><label class="label" for="allocation-target-name">Instrument name</label><input id="allocation-target-name" class="field" placeholder="Auto-filled after verification" required></div>'''
if old not in s: raise SystemExit('target ticker block missing')
s=s.replace(old,new,1)

marker='''    function updateAllocationPreview() {\n'''
insert='''    const allocationLookupState={funding:0,target:0};\n\n    function resetAllocationVerification(kind){\n        allocationLookupState[kind]++;\n        const status=el(`allocation-${kind}-status`);\n        if(status){ status.textContent='Ticker changed · verify again.'; status.className='text-[10px] font-bold text-gray-400 mt-1.5'; }\n    }\n\n    async function verifyAllocationTicker(kind){\n        const symbolEl=el(`allocation-${kind}-symbol`);\n        const status=el(`allocation-${kind}-status`);\n        const symbol=symbolEl.value.trim().toUpperCase();\n        const tradeDate=el('allocation-date').value;\n        symbolEl.value=symbol;\n        if(!symbol || !tradeDate){ status.textContent='Enter ticker and trade date to verify.'; status.className='text-[10px] font-bold text-gray-400 mt-1.5'; return; }\n        const token=++allocationLookupState[kind];\n        status.textContent='Checking market data…'; status.className='text-[10px] font-bold text-blue-600 mt-1.5';\n        try{\n            const data=await apiFetch(`/admin/${PORTFOLIO}/instrument-lookup?symbol=${encodeURIComponent(symbol)}&trade_date=${encodeURIComponent(tradeDate)}`);\n            if(token!==allocationLookupState[kind]) return;\n            const previous=data.used_previous_session ? ` · previous session ${prettyDate(data.price_date)}` : ` · close ${prettyDate(data.price_date)}`;\n            if(kind==='funding'){\n                el('allocation-funding-price').value=Number(data.reference_close).toFixed(4);\n                status.textContent=`✓ Verified · ${data.name}${data.exchange?' · '+data.exchange:''} · ${Number(data.held_quantity||0).toLocaleString('en-GB')} units held${previous}`;\n            }else{\n                el('allocation-target-name').value=data.name||symbol;\n                if(['GBP','USD','EUR'].includes(data.currency)){ el('allocation-target-currency').value=data.currency; }\n                if(data.currency==='GBP') el('allocation-target-fx').value='1';\n                el('allocation-target-price').value=Number(data.reference_close).toFixed(4);\n                status.textContent=`✓ Verified · ${data.name}${data.exchange?' · '+data.exchange:''} · ${data.currency}${previous}`;\n            }\n            status.className='text-[10px] font-black text-emerald-700 mt-1.5';\n            updateAllocationPreview();\n        }catch(error){\n            if(token!==allocationLookupState[kind]) return;\n            status.textContent=`✕ ${error.message}`; status.className='text-[10px] font-bold text-red-600 mt-1.5';\n        }\n    }\n\n    el('allocation-funding-symbol').addEventListener('input',()=>resetAllocationVerification('funding'));\n    el('allocation-target-symbol').addEventListener('input',()=>resetAllocationVerification('target'));\n    el('allocation-funding-symbol').addEventListener('blur',()=>verifyAllocationTicker('funding'));\n    el('allocation-target-symbol').addEventListener('blur',()=>verifyAllocationTicker('target'));\n    el('allocation-date').addEventListener('change',()=>{ verifyAllocationTicker('funding'); if(el('allocation-target-symbol').value.trim()) verifyAllocationTicker('target'); });\n\n''' + marker
if marker not in s: raise SystemExit('allocation preview marker missing')
s=s.replace(marker,insert,1)

old="""            el('allocation-form').reset(); el('allocation-funding-symbol').value='VUAG.L'; el('allocation-funding-fees').value='0'; el('allocation-target-currency').value='GBP'; el('allocation-target-fx').value='1'; el('allocation-target-fees').value='0'; setTodayDefaults(); updateAllocationPreview();\n"""
new="""            el('allocation-form').reset(); el('allocation-funding-symbol').value='VUAG.L'; el('allocation-funding-fees').value='0'; el('allocation-target-currency').value='GBP'; el('allocation-target-fx').value='1'; el('allocation-target-fees').value='0'; setTodayDefaults(); el('allocation-funding-status').textContent='Enter a ticker to verify.'; el('allocation-funding-status').className='text-[10px] font-bold text-gray-400 mt-1.5'; el('allocation-target-status').textContent='Enter a ticker to verify.'; el('allocation-target-status').className='text-[10px] font-bold text-gray-400 mt-1.5'; updateAllocationPreview();\n"""
if old not in s: raise SystemExit('allocation reset marker missing')
s=s.replace(old,new,1)

p.write_text(s,encoding='utf-8')
print('allocation lookup UI patched')
